"""Rebuild static shells from local strings; no dependency or build step to view them."""
from pathlib import Path
import json
ROOT = Path(__file__).parent
PRODUCT = 'SVS Performance Monitor'  # Rename here and in app.js PRODUCT, then regenerate.

def shell(page, title, body, preview='', cls=''):
    nav = ''.join(f'<a href="{p}.html"'+(' aria-current="page"' if p == page else '')+f'>{label}</a>' for p,label in [('dashboard','Dashboard'),('log','Game log'),('settings','Settings')])
    markup = f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="color-scheme" content="dark light"><title>{PRODUCT} · {title}</title><link rel="icon" href="brand/logo-64.png" type="image/png"><link rel="stylesheet" href="styles.css"><script defer src="fixtures.js"></script><script defer src="app.js"></script></head>
<body class="{cls}" data-page="{page}"><a class="skip" href="#main">Skip to content</a>
<header class="masthead"><div class="wrap header-inner"><a class="identity" href="dashboard.html"><img src="brand/logo-64.png" alt="" width="40" height="40"><div><div class="product">{PRODUCT}</div><div class="studio">SimVizion Studios</div></div></a><nav aria-label="Main navigation">{nav}</nav></div></header>
<main id="main" class="wrap {('form-page' if page=='settings' else 'welcome' if page=='welcome' else '')}">{body}</main>
{'' if page=='log' else '<footer class="wrap footer"><span>SimVizion Studios · '+PRODUCT+'</span><span>Watches the game from outside. Nothing is added to the game.</span></footer>'}
<aside class="preview" aria-label="Design preview controls"><div class="wrap row"><span class="caption">Design preview · sample data</span>{preview}<label for="theme">Appearance</label><select id="theme"><option value="system">Use device setting</option><option value="dark">Dark</option><option value="light">Light (proposed)</option></select><a href="tray.html">Tray preview</a><a href="welcome.html">Welcome preview</a></div></aside>
<div class="toast" id="toast" role="status" hidden><button aria-label="Dismiss message" id="dismiss">×</button><span id="toast-text"></span></div></body></html>'''
    (ROOT / f'{page}.html').write_text(markup, encoding='utf-8')

shell('dashboard','Dashboard','''
<div class="page-title"><h1>Dashboard</h1><div class="row"><span class="status" id="game-status"></span><span class="tag" id="mode"></span></div></div>
<section class="verdict" aria-labelledby="verdict"><div class="eyebrow">Farming Simulator 25</div><h2 id="verdict"></h2><p id="reason"></p>
<div class="metrics"><div class="metric"><div class="metric-label">FPS</div><div class="metric-value" id="fps"></div><div class="meta">Frames each second</div></div><div class="metric"><div class="metric-label">1% low</div><div class="metric-value" id="low"></div><div class="meta">A guide to the slowest frames</div></div><div class="metric"><div class="metric-label">Frame time</div><div class="metric-value" id="ft"></div><div class="meta">Average · lower is smoother</div></div></div></section>
<div id="frame-banner" class="banner" style="margin-top:16px" hidden></div>
<section class="card trend" id="trend"><div class="row between"><h2>Frame times</h2><span class="meta">Last 5 minutes · milliseconds</span></div><div id="frame-chart"></div><div class="legend"><span>Frame time</span><span class="cpu">Processor work – dashed</span><span class="gpu">Graphics work · dotted</span></div><p class="meta" id="trend-summary"></p></section>
<details class="small"><summary>What does this mean?</summary><p>FPS counts frames each second. Higher usually feels smoother. Frame time is how long each frame takes; lower is better. The 1% low helps you spot uneven performance even when the average FPS looks good.</p><p style="margin-top:8px">The verdict is a guide for this moment. A frame rate cap, a menu or loading can change it. Compare the same place in the game when testing a change.</p></details>
<details id="advanced"><summary>Advanced <span class="meta">Loads, memory, threads and plugins</span></summary><div class="advanced-grid">
<section class="card panel span-all"><div class="row between"><h2>Loads and memory</h2><span class="meta" id="process"></span></div><div class="readout" id="loads"></div></section>
<section class="card panel span-all"><div class="row between"><h2>Load over time</h2><span class="meta">Last 5 minutes · percent</span></div><div id="load-chart"></div><div class="legend"><span class="cpu">Main thread busy – dashed</span><span class="gpu">GPU 3D · dotted</span></div></section>
<section class="card panel span-all"><h2>Per-frame detail</h2><div class="readout" id="frame-details"></div><p class="meta" id="capture-note" style="margin-top:12px"></p></section>
<section class="card panel"><h2 class="section-head">Main thread: where the time goes</h2><table><thead><tr><th scope="col">Module / kind</th><th scope="col" class="numeric">Share / samples</th></tr></thead><tbody id="modules"></tbody></table><p class="meta" id="sampling" style="margin-top:12px"></p><p class="small" style="margin-top:8px">A plugin’s share counts its own code. Game code it calls counts as the game. Lua mods also count as the game. These shares are not the total cost of a plugin.</p></section>
<section class="card panel"><h2 class="section-head">Busiest game threads</h2><table><thead><tr><th scope="col">Thread ID</th><th scope="col" class="numeric">Busy · one core</th></tr></thead><tbody id="threads"></tbody></table></section>
<section class="card panel span-all"><div class="row between"><h2>FSPluginHost plugins</h2><a href="log.html">Open game log →</a></div><p class="small" id="host" style="margin-top:8px"></p><p class="meta" id="host-written" style="margin-top:4px"></p><div class="plugin-list" id="plugins"></div><p class="small" id="services" style="margin-top:12px"></p></section>
<section class="card panel span-all"><h2 class="section-head">Diagnostics</h2><p class="small mono" id="diagnostics"></p></section>
</div></details>
''','''<label for="scenario">Scenario</label><select id="scenario"><option value="gpu">Graphics card limit · full</option><option value="cpu">Processor limit · full</option><option value="waiting">Waiting for the game</option><option value="setup">Frame times not set up · basic</option><option value="basic">Frame times off · basic</option><option value="neither">Neither is the limit</option><option value="both">Both near the limit</option><option value="mixed">Mixed loads · basic</option><option value="unknown">Load unavailable · basic</option><option value="starting">Starting frame capture</option><option value="no-frames">No frames yet</option><option value="missing">Frame tool missing</option><option value="error">Capture error</option><option value="exited">Capture stopped</option><option value="disconnected">Connection lost</option><option value="no-host">No plugins installed</option><option value="sampling-off">Sampling off</option></select>''')

def setting(title, desc, control, full=False):
    return f'<div class="setting"><div><div class="setting-title">{title}</div><p>{desc}</p></div>{control}</div>'
def checkbox(id, label, checked=False):
    return f'<label class="check-target" title="{label}"><input id="{id}" type="checkbox" aria-label="{label}"'+(' checked' if checked else '')+'></label>'

settings = '<div class="page-title"><h1>Settings</h1><span class="tag" id="settings-origin">This PC</span></div><div id="settings-notice" role="status" class="banner" hidden></div><form id="settings-form" class="stack">'
settings += '<section class="card"><h2>General</h2>'+setting('Start SVS Performance Monitor when Windows starts','Keep it ready when you want to play.',checkbox('startup','Start SVS Performance Monitor when Windows starts',True))+'</section>'
settings += '<section class="card" id="frame-times"><h2>Frame times</h2>'+setting('Show frame times (FPS and stutter)','Windows will ask for permission once, then sign out and back in. After that, SVS Performance Monitor can show FPS without full permissions.','<div class="actions"><span class="tag" id="setup-status">Not set up</span><button type="button" class="primary" id="setup">Set up</button></div>')+'</section>'
settings += '<section class="card"><h2>Phone and home network</h2>'+setting('Let my phone or other computers at home open the dashboard','They can also see your game log, which shows your Windows user name and mod list. Use a trusted private home network. Windows will ask once.',checkbox('lan','Let my phone or other computers at home open the dashboard'))+'<p class="meta" id="network-address">Home network sharing is off.</p></section>'
settings += '<section class="card"><h2>Advanced</h2>'+setting('Run with full permissions','Only needed for the detailed mod breakdown. Windows asks once.',checkbox('elevated','Run with full permissions'))+setting('Show what the game’s main loop spends time on','Briefly pauses the game hundreds of times a second; it slows the game a little (a few percent). Leave off for timing-sensitive comparisons, or keep it the same for both runs.',checkbox('sampling-enabled','Show what the game’s main loop spends time on'))+setting('Open the dashboard when SVS Performance Monitor starts','Open it in your usual browser.',checkbox('open-browser','Open the dashboard when SVS Performance Monitor starts',True))+'''<div class="field"><label for="profile">Farming Simulator settings folder</label><input id="profile" type="text" value="C:/Users/Player/Documents/My Games/FarmingSimulator2025" spellcheck="false"><span class="meta">Found automatically. Change only if you use a different folder.</span></div><div class="field"><label for="port">Port</label><input id="port" type="number" min="1" max="65535" value="8765" aria-describedby="port-help port-error"><span id="port-help" class="meta">Changing this address takes effect after SVS Performance Monitor restarts.</span><span id="port-error" class="field-error" hidden>⚠ Enter a whole number from 1 to 65535.</span></div></section><div class="row between"><p id="save-note" class="small">Preview only. Changes are not saved to your PC.</p><button class="primary" type="submit" id="save">Save changes</button></div></form>'''
shell('settings','Settings',settings,'''<label for="settings-state">View</label><select id="settings-state"><option value="pc">This PC · not set up</option><option value="phone">Phone · read-only</option><option value="ready">Frame times ready</option><option value="signout">Sign out needed</option><option value="cancelled">Permission cancelled</option><option value="failure">Setup failed</option></select>''')
shell('welcome','Welcome','''<section class="card"><div class="eyebrow">Welcome · SimVizion Studios</div><h1>Know what holds your game back.</h1><p class="welcome-intro">SVS Performance Monitor shows whether your processor or graphics card is limiting Farming Simulator 25. It watches from outside the game, so nothing is added to the game.</p><div class="feature"><h2>See FPS and spot stutter</h2><p>Set up frame times to see how smoothly the game runs. Windows will ask for permission once, then sign out and back in.</p><div class="row"><button class="primary" id="welcome-setup">Set up frame times</button><span class="small" id="welcome-status" role="status">You can also do this later in Settings.</span></div></div><label class="choice"><input type="checkbox" id="welcome-startup">Start SVS Performance Monitor when Windows starts</label><div class="row between"><p class="small">SVS Performance Monitor stays in the notification area while it runs.</p><a class="button" href="dashboard.html?state=waiting">Open dashboard →</a></div></section>''')
shell('log','Game log','''<div class="page-title"><h1>Game log</h1><span class="status" id="log-status" role="status"></span></div><div class="log-tools"><label for="filter" class="small">Find text in the log</label><input id="filter" type="search" placeholder="Filter lines…" autocomplete="off" autocapitalize="off" spellcheck="false"><div class="row between"><div class="filters"><button id="bErr" aria-pressed="false">Errors</button><button id="bWarn" aria-pressed="false">Warnings</button><button id="bFail" aria-pressed="false">FAIL</button></div><div class="actions"><button id="pause" aria-pressed="false">Pause</button><button id="clear">Clear</button></div></div><p class="meta">Selected levels are combined. Text ignores letter case. Clear affects this view only.</p></div><div class="log-viewport" id="log" role="region" aria-label="Game log lines" tabindex="0"></div><div class="log-bottom"><span class="meta" id="log-count"></span><button class="primary" id="jump" hidden>Jump to live ↓</button></div>''','''<label for="log-state">Scenario</label><select id="log-state"><option value="live">Live · sample lines</option><option value="paused">Paused</option><option value="scrolled">Reading older lines</option><option value="reconnecting">Reconnecting</option><option value="waiting">Waiting for lines</option><option value="restart">Game restarted</option><option value="gap">Lines were missed</option></select>''','log-page')
shell('tray','Tray and icons','''<div class="page-title"><h1>Notification area</h1><span class="tag">Windows tray · design preview</span></div><div class="advanced-grid"><section class="card"><h2 class="section-head">Tray menu</h2><div class="tray-menu" aria-label="Tray menu preview"><div class="status-line" id="tray-status">Waiting for the game</div><a href="dashboard.html">Open dashboard</a><a href="settings.html">Settings</a><button id="exit">Exit</button></div><p class="small" style="margin-top:16px">Open the dashboard with a double-click. Right-click for this menu.</p><p class="meta" style="margin-top:8px">The actual Windows menu uses native keyboard and dismissal behavior.</p></section><section class="card"><h2>Icon sources · 16 and 32 px</h2><div id="icon-gallery"></div><p class="small">Waiting uses a neutral outline. Watching uses a green outline with a check. Read the verdict in the tooltip; tiny limit badges would be hard to tell apart.</p></section></div>''','''<label for="tray-state">Status</label><select id="tray-state"><option value="waiting">Waiting for the game</option><option value="watching">Watching the game</option><option value="cpu">Your processor is the limit</option><option value="gpu">Your graphics card is the limit</option></select>''')

# Local, explicitly synthetic examples retain the exact camelCase snapshot shape.
waiting = json.loads((ROOT/'sample_snapshot_waiting.json').read_text(encoding='utf-8-sig'))
gpu = dict(waiting)
gpu.update(time='2026-11-08T14:32:05-09:00', mode='full', attached=True,pid=18420,process='FarmingSimulator2025Game',processCpuPct=18.4,mainThreadBusyPct=62.0,gpu3DPct=98.0,gpuDedicatedMb=7680,workingSetMb=11980,privateMb=13414,mainThreadSamples=248,elevated=False,note='')
gpu['topThreads']=[dict(tid=19432,busyPct=62,main=True),dict(tid=19484,busyPct=37,main=False),dict(tid=20112,busyPct=24,main=False),dict(tid=20136,busyPct=12,main=False)]
gpu['mainThreadModules']=[dict(name=n,kind=k,percent=p,samples=s) for n,k,p,s in [('FarmingSimulator2025Game.exe','Game',70.2,174),('nvwgf2umx.dll','Graphics',16.1,40),('FS25_3dTerrain','Plugin',6.5,16),('FSPMesh','Plugin',3.2,8),('fsp.dll','Host',2.0,5),('ntdll.dll','Windows',2.0,5)]]
gpu['frames']=dict(state='running',hint='',frames=58,fps=58.2,frameTimeAvgMs=17.2,frameTimeP50Ms=16.9,frameTimeP99Ms=24.8,low1PctFps=40.3,cpuBusyMs=8.1,cpuWaitMs=9.1,gpuBusyMs=16.5,gpuWaitMs=0.7,gpuLatencyMs=18.1,displayLatencyMs=34.4,presentMode='Composed: Flip',runtime='DXGI')
gpu['verdict']=dict(label='GPU-bound',reason='GPU busy 16.5 ms, CPU busy 8.1 ms, frame 17.2 ms')
gpu['fsp']=json.loads(json.dumps(waiting['fsp']))
gpu['fsp']['written']=gpu['time']
(ROOT/'sample_snapshot_gpu.json').write_text(json.dumps(gpu,indent=2),encoding='utf-8')
(ROOT/'fixtures.js').write_text('/* Synthetic GPU sample; waiting sample is the supplied real capture. No network requests. */\nwindow.FIXTURES = '+json.dumps(dict(waiting=waiting,gpu=gpu),ensure_ascii=False)+';\n',encoding='utf-8')

for name,color,watch in [('app','#42CDD2',False),('tray-waiting','#A6B8BC',False),('tray-watching','#A7D5A0',True)]:
    check='<path d="m9 11 1.5 1.5L14 9" stroke="#A7D5A0"/>' if watch else ''
    svg=f'''<svg xmlns="http://www.w3.org/2000/svg" width="32" height="32" viewBox="0 0 16 16"><title>{PRODUCT} {name}</title><g fill="none" stroke="{color}" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><rect x="1.5" y="2.5" width="13" height="10" rx="2"/><path d="M3.5 8.5h2L7 5l2 5 1.5-2h2"/>{check}</g></svg>'''
    if watch:
        svg=svg.replace('<path d="M3.5 8.5h2L7 5l2 5 1.5-2h2"/>','<path d="M3.5 8.5h2L7 5l1.5 4"/>')
    if name == 'app':
        svg=svg.replace('<g fill="none"','<rect width="16" height="16" rx="3" fill="#071215"/><g fill="none"')
    (ROOT/'icons'/f'{name}.svg').write_text(svg,encoding='utf-8')
    if name.startswith('tray-'):
        (ROOT/'icons'/f'{name}-light.svg').write_text(svg.replace('#A6B8BC','#48636A').replace('#A7D5A0','#31632B'),encoding='utf-8')
print('Created five static HTML mockups, local fixtures and five SVG icons.')
